import{H as e,V as t,et as n,j as r}from"./chunks/framework.ChZHrXbO.js";var i=JSON.parse(`{"title":"MySQL概述","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-overview.md","filePath":"mysql/mysql-overview.md"}`),a={name:`mysql/mysql-overview.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="mysql概述" tabindex="-1">MySQL概述 <a class="header-anchor" href="#mysql概述" aria-label="Permalink to “MySQL概述”">​</a></h1><h2 id="_1-数据库相关概念" tabindex="-1">1.数据库相关概念 <a class="header-anchor" href="#_1-数据库相关概念" aria-label="Permalink to “1.数据库相关概念”">​</a></h2><p><strong>数据库（DB）</strong>：按照一定的数据结构来组织、存储和管理数据的仓库</p><p><strong>数据库管理系统(DBMS)</strong>：一种操纵和管理数据库的大型软件，用于创建、使用和维护数据库</p><p><strong>关系型数据库（RDBMS）</strong>：由多张相互连接的二维表组成的数据库</p><p><strong>非关系型数据库</strong>：泛指非关系型数据库，是对关系型数据库的补充</p><p><strong>结构化查询语言（SQL）</strong>：一种操作关系型数据库的编程语言，定义了一套操作关系型数据库统一SQL标准</p><h2 id="_2-mysql数据库概述" tabindex="-1">2.MySQL数据库概述 <a class="header-anchor" href="#_2-mysql数据库概述" aria-label="Permalink to “2.MySQL数据库概述”">​</a></h2><h3 id="_2-1-安装和卸载" tabindex="-1">2.1 安装和卸载 <a class="header-anchor" href="#_2-1-安装和卸载" aria-label="Permalink to “2.1 安装和卸载”">​</a></h3><p>下载地址：</p><p><a href="https://dev.mysql.com/downloads/windows/installer/8.0.html" target="_blank" rel="noreferrer">https://dev.mysql.com/downloads/windows/installer/8.0.html</a></p><p>Windows安装和下载MySQL参考如下资料即可：</p><p><a href="assets/MySQL%E5%AE%89%E8%A3%85.pdf">MySQL安装.pdf</a></p><p><a href="assets/MySQL%E5%8D%B8%E8%BD%BD%E6%96%87%E6%A1%A3-Windows%E7%89%88.pdf">MySQL卸载文档-Windows版.pdf</a></p><p>Linux系统安装MySQL软件的操作可以参考下面这个资料：</p><p><a href="assets/Linux%E8%BD%AF%E4%BB%B6%E5%AE%89%E8%A3%85-MySQL.pdf">Linux软件安装-MySQL.pdf</a></p><h3 id="_2-2-启动与停止" tabindex="-1">2.2 启动与停止 <a class="header-anchor" href="#_2-2-启动与停止" aria-label="Permalink to “2.2 启动与停止”">​</a></h3><p>1.管理员连接（以管理员方式打开命令行窗口）：</p><p>启动：<code>net start mysql80</code></p><p>停止：<code>net stop mysql80</code></p><ul><li>默认mysql是开机自动启动的</li></ul><p>2.客户端连接：</p><p>方式一：开始菜单找到MySQL提供的客户端命令行工具<code>MySQL 8.0 Command Line Client</code></p><p>方式二：系统自带的命令行工具执行指令<code>mysql [-h 127.0.0.1] [-P 3306] -u root -p</code></p><ul><li>方式二需要配置环境变量<code>C:\\Program Files\\MySQL\\MySQL Server 8.0\\bin\\</code></li></ul>`,25)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};